"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[2680],{2680:function(a){a.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Guriga","about":"Aniga igu saabsan","portfolio":"Portfolio","projects":"Mashaariicda Mareegaha","tiger":"Luuqadda Shabeelka","portfolio_translator":"Turjumaan Portfolio","formatter":"JSON & YAML Formatter","contact":"ila soo xidhiidh"},"home":{"title":"Injineer buuxa oo buuxa | Badeecada & Nidaamyada","animated":{"first":"Injineer Buuxa oo Sare","second":"Nidaamyada & Dhisaha Dhismaha","third":"Injineer wax soo saarka SaaS","fourth":"Software lagu kalsoonaan karo, Natiijooyinka Ganacsiga"},"footer":"Websaydhku hadda waa lagu turjumay oo lagu heli karaa in ka badan 100 luqadood!","descriptionA":"Injineer buuxa oo buuxa oo leh 6+ sano oo waayo-aragnimo ah ka qaadashada alaabooyinka shuruudaha mugdiga ah ee nidaamyada wax-soo-saarka la isku halayn karo. Waxaan naqshadeeyaa naqshadaha ka dambeeya React, Angular, .NET, Node.js, Java, C#, Go, iyo codsiyada SQL: xuduudo adeeg oo cad, moodooyinka xogta waara, qaababka gelitaanka aaminka ah, iyo kooxaha dariiqyada gaarsiintu waxay ku shaqayn karaan si kalsooni leh.","descriptionB":"Shaqadaydu waxay ku xidhaa go\'aamada injineernimada iyo natiijooyinka ganacsiga. Laga soo bilaabo dhismo-qiyaasta SaaS oo u beddela xogta xaashida soo jeedinta diyaarka ah ee macmiilka si ay dakhli-abuurista shabakadaha internetka, waxaan u dhisaa software ku wareegsan socodka shaqada, khatarta, iyo qiimaha la qiyaasi karo ee muhiimka u ah dadka isticmaalaya.","portfolio_button":"Bootfooliyadayda","contact_button":"ila soo xidhiidh","about_button":"Aniga igu saabsan"},"about":{"title":"Aniga igu saabsan","personal_summary":{"title":"Kooban Shaqsiyeed","text":"Waxaan ahay injineer buuxa oo buuxa oo fadhigiisu yahay Orlando, FL kaasoo iska leh dariiqa dhibaatada alaabta ilaa natiijada wax soo saarka. Waxaan sameeyaa doorashooyinka tignoolajiyada ee adeegga nidaamka: NET iyo Hay\'adda Qaabdhismeedka Guud marka si xooggan loo habeeyey iyo arrin adkaysi la tijaabin karo; Xaglo ama falcelin marka adag socodka shaqadu wuxuu u baahan yahay interface la ilaalin karo; Node.js ama Go marka API, is dhexgalka, ama qalabka waxqabadka sare u baahan yahay runtime diirada saaraya. Dhammaan badeecadaha SaaS, qulqulka shaqada gudaha, iyo macaamiisha u jeedda, waxaan ku hogaamiyaa ganacsiyo cad, nashqad sugan oo adkeysi leh, tijaabin toos ah, iyo dhaqamada gaarsiinta kooxaha kaalmeeya in ay soo raraan software qiimo leh iyaga oo aan ka tagin deynta shaqada."},"professional_experience":{"title":"Khibrad Xirfadeed","entries":[{"jobtitle":"Injineer Software Sare","where":"Naqshad Interactive","date":"2025 - Hadda"},{"jobtitle":"Injineer Software","where":"Orion180 Caymiska","date":"2024 - 2025"},{"jobtitle":"Injineer Software","where":"SupremeMC","date":"2020 - 2024"},{"jobtitle":"Injineer Software","where":"Dardar gelinta Waxbarashada","date":"2023"},{"jobtitle":"Injineer Software-ka Hogaaminaya (Barnaamijka Ardayga)","where":"Jaamacadda Clemson ee barnaamijka GDI","date":"2021 - 2022"},{"jobtitle":"Kormeeraha Miiska","where":"Jaamacadda Clemson","date":"2021 - 2022"}]},"technical_skills":{"title":"Xirfadaha Farsamada","header1":"Barnaamijyada Luuqadaha","header2":"Qaab-dhismeedka & Maktabadaha","header3":"Qalabka & Farsamada"},"services":{"title":"Adeegyadayda","entries":[{"title":"Injineernimada Raajada Buuxa","text":"Waxaan horseedaa gaarsiinta badeecada dhamaadka-ilaa-dhamaadka: tarjumaadda qulqulka shaqada ganacsiga ee xuduudaha nidaamka, moodooyinka xogta, API-yada, iyo is-dhexgalka, ka dibna shaqada ku sita iyada oo la adeegsanayo tijaabinta, geynta, iyo ku celcelin. Hadafka waa software ay kooxi horumarin karto oo shaqayn karto, ma aha ururinta shaashadaha kala go\'an."},{"title":"Qalabka & Dhismaha Platform","text":"Waxaan doortaa habab iyo qaabab ku salaysan dhibka: adeegyada .NET ee lakabka ah ee goobaha ganacsiga, Angular-ka ka kooban ama codsiyada falcelinta ee hawlgallada adag, xidhiidhka moodooyinka xogta ee socodka shaqada ee lala xisaabtami karo, iyo isku dhafka loogu talagalay qaababka guul darrida, xakamaynta gelitaanka, iyo ilaalinta maskaxda."},{"title":"Wax-soo-saar-Diyaar ah","text":"Waxaan la dhisaa xaqiiqooyinka ka dib bilawga aragtida: siraha laga ilaaliyay xakamaynta isha, dariiqyada hayaanka xogta ee cad, oggolaanshaha doorka ku salaysan, ansixinta xuduudaha nidaamka, imtixaanada otomaatiga ah, wacyigelinta CI/CD, iyo indho-indheyn la taaban karo. Kuwani waa faahfaahinta u beddela prototype ka mid ah software la isku halleyn karo."}]}},"portfolio":{"title":"Portfolio","filter_by":"Shaandhayso Bootfooliyada By:","entries":{"biblioteca":{"title":"Biblioteca JSON","text":"Dhuumaha meelaynta ku salaysan Python oo hal il habaysan u beddela faylal la heli karo oo caalami ah. Waxay u maamushaa xogta tarjumaadda sidii nidaam la sii wadi karo halkii ay gacanta ku nuqul ka lahayd, taasoo u oggolaanaysa goobta inay ku cabbirto in ka badan 100 luqadood iyo inay ka dhigto mid caalami ah karti hawleed halkii ay ka ahaan lahayd muuqaal hal mar ah.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Isku xidh Afar","text":"Qoys weyn oo ka badan 50+ fulinta ciyaarta Connect Four. Mashruucan waxaa ka mid ah hirgelinta in ka badan 30 luqadaha barnaamijyada kala duwan, oo ay ku jiraan Java, C++, Python, JavaScript, iyo in ka badan. Intaa waxaa dheer, waxa kale oo ka mid ah in ka badan 20+ qaabab kala duwan ama qaabab kale, oo ay ku jiraan React.js, Ruby on Rails, ASP.NET, iyo in ka badan.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"App-ka raashinka","text":"Codsi buuxa oo NET 9 Blazor Server ah oo muujinaya naqshadaynta ula kac ah ee socodka shaqada ganacsiga. Kala qaybsanaanta maamulaha/adeegga/ kaydka ayaa ilaalinaya sharciyada codsiga, helitaanka xogta, iyo soo bandhigida si madax banaan oo la tijaabin karo; Qaab-dhismeedka Hay\'adda Xuddunta waxay bixisaa adkaysi waara; iyo qolka tijaabada dhamaystiran wuxuu ilaaliyaa dabeecadda marka alaabtu soo baxdo.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Mashruuca Interop","text":"Tixraaca wada shaqaynta luqadda iskutallaabta ah oo ka kooban 15 luqadood oo barnaamij ah iyo 18 qaab oo fulin ah. Mashruucu waxa uu baaraa xuduudka halka nidaamyadu inta badan noqdaan kuwa jilicsan: habsocodka qandaraasyada, xog-isweydaarsiga, habdhaqanka runtime, iyo waddooyinka isdhexgalka ee soo noqnoqda. Waxay ka tarjumaysaa hababka fikirka loo baahan yahay marka alaabtu ka weyn tahay hal xidhmo.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Diiwaanka Alaabta","text":"POS-buuxa iyo socodka shaqada alaabada oo lagu dhisay xagal 17+ iyo Node.js. Waxay qaabaysaa walaacyada hawlgelinta ee nidaamka B2B: isticmaalayaasha la xaqiijiyay, kontoroolka gelitaanka doorka-ku-salaysan, saxnaanta alaabada, iyo socodka lacag-bixinta jees-jeeska ah. Mashruucu waxa loo nashqadeeyay shaqada dhabta ah ee ay kooxda diwaangelintu qabtaan, ma aha oo kaliya buug-tusaha qaab-dhismeedka.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON & YAML Auto Formater","text":"JSON ku salaysan browserka iyo ansaxinta YAML iyo qalab lagu dhisay Go oo lagu soo ururiyay WebAssembly. U raridda mishiinka wax-kala-soocidda ee WASM waxay ka dhigaysaa is-dhexgalka mid ka jawaabaya oo maxalli ah browserka iyada oo la adeegsanayo parser-ka dhabta ah si loo qabto gelinta aan sax ahayn. Waa tusaale diirada saaraya doorashada qaab dhismeedka runtime ee waxqabadka, qaadida, iyo aaminaadda isticmaalaha.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Matoorka Qaadista","text":"Dhisme lagu qiyaaso SaaS oo lagu dhisay kharash badan, socodka shaqada qandaraasleyaasha khaladka u nugul. Alaabada React + Express waxa ay soo gelisaa xogta CSV iyo Excel, waxa ay maabka tiirar aan iswaafaqayn oo qaab domain la isticmaali karo, xisaabiya qodista jeexjeexyada iyo tirada shaqada dhulka, raadraaca shaqada iyo calaamadee, oo soo saara macaamiisha-u diyaarsan PDF iyo soo jeedinta Word. Kani waa injineer nololeed oo buuxa: falanqaynta xogta, xeerarka xisaabinta, socodka shaqada ee hawlwadeenka oo la qurxiyey, iyo wax-soo-saarka caawiya ganacsigu inuu ka guuro agabka cayriin una guuro dalab.","link":"https://github.com/pattygcoding/takeoff-engine"},"minecraft_json_generator":{"title":"Minecraft JSON Generator","text":"Matoor fudud oo JSON ah oo lagu dhisay Python oo loogu talagalay agabka Minecraft & xidhmooyinka xogta. Mashruucan waxaa loo isticmaalaa in lagu soo saaro faylasha JSON ee qaababka Minecraft, oo ay ku jiraan alaabta gaarka ah, blocks, iyo qaybaha. Aad bay faa\'iido u leedahay ma aha oo kaliya abuurista xirmooyinka xogta gaarka ah, laakiin mods sidoo kale iyada oo loo marayo qaabka beddelka magaca.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Waayo-aragnimadayda Waxbarasho","text":"Mashaariicdayda gaarka ah waxaa barbar socda, waxaan sidoo kale ka helay xirfado badan oo khibrad waxbarasho ah. Riix halkan si aad u aragto profile-kayga LinkedIn wixii macluumaad dheeraad ah.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Waayo-aragnimadayda Xirfadeed","text":"Lix sano oo lagu daray waayo-aragnimada injineernimada xirfadeed ee kooxaha wax soo saarka, goobaha ganacsiga, iyo software soo-jeeda macaamiisha. Shaqadaydu waxa ka mid ahaa dhisidda lakabyo arji oo la joogteyn karo, ka wada shaqaynta qaybaha qaybinta, iyo samaynta go\'aamo farsamo ee wareegga nolosha badeecada, shaqaynaysa khatarta, iyo lahaanshaha muddada dheer ee aragtida.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Patrick Goodwin Portfolio Website","text":"Wax soo saar-maskaxeed faylalka falcelinta kaaso ula dhaqma gelitaanka iyo gaadhista caalamiga ah sida shuruudaha injineernimada. Waxaa ka mid ah dhuumaha tarjumaadda la joogteyn karo ee 100+ luqadood, qalab is dhexgal ah oo uu taageeray WebAssembly, ka jawaab celin iyo qaababka UI oo la heli karo, iyo qaab dhismeed mashruuc loogu talagalay in ay koraan marka shaqo cusub la soo raro.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrick\'s Lua Script Library","text":"Maktabad faa\'iido leh oo ah qoraallada Lua ee tixraaca mustaqbalka. Maktabaddan waxa loo isticmaalaa in lagu habeeyo hawlaha ku jira qoraallada Lua, kuwaas oo ku anfacaya hawlaha hawl-qabadka u baahan, maadaama Lua inta badan tahay luqad qoraal ah oo ka dhaqso badan Python iyo Ruby labadaba.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Patrick\'s Microsoft Excel Spreadsheet Scripts (VBA)","text":"Maktabad faa\'iido leh oo ah qoraallada VBA ee Microsoft Excel. Maktabaddan waxa loo istcmaalay in si otomaatig ah loogu sameeyo hawlaha ku jira xaashiyaha Excel.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Patrick\'s Neovim Config","text":"Qaabayntayga gaarka ah ee Neovim Mashruucan waxaa loo isticmaalaa in lagu habeeyo Neovim sida aan jeclahay, oo ay ku jiraan furayaasha gaarka ah, mawduucyada, iyo plugins. Mashruucan waxa loo istcimaalay in Neovim uu ka dhigo mid isticmaale-saaxiibtinimo iyo hufnaan u leh isticmaalkayga gaarka ah.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Dhaliyaha Khariidadda Patrick","text":"Qalabka warbixinta geospatial Python oo lagu dhisay GeoPandas iyo Matplotlib si loo soo saaro khariidado gobolka iyo gobolka Mareykanka. Waxa ay xogta juqraafiga u rogtaa farshaxanno la akhriyi karo, oo tusinaya maskaxda dhuumaha xogta: dooro maktabadaha goobta saxda ah, caadi ka dhig agabka, oo soo saara wax soo saar taageer go\'aamo cad cad.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrick\'s PowerShell Script Script","text":"Maktabad waxtar leh oo ah qoraallada PowerShell ee tixraaca mustaqbalka. Faa\'iido u leh astaanta qoraalka profile $, waxaan u arkaa mid aad waxtar u leh si otomaatig ah hawlaha Windows terminalka, maadaama aan ahay isticmaale joogto ah Windows OS.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Patrick\'s Ruby Script Library","text":"Maktabad faa\'iido leh oo ah qoraallada Ruby si loo tixraaco mustaqbalka. Faa\'iido u leh mustaqbalka Ruby on Rails fikradaha horumarinta.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"Dhisaha Xirfadaha PDF","text":"Socod-hawleed dokumenti-jiil ah oo lagu dhisay Python, Pdfkit, Jinja2, HTML, iyo xogta JSON habaysan. Waxay ka soocaa xogta dib loo isticmaali karo iyo qaababka soo bandhigida si ay u soo saarto dib u habaynta PDF ee joogtada ah, qaab wax ku ool ah oo lagu dhimayo shaqada gacanta iyo samaynta dukumentiyada ganacsiga lagu celin karo.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Mashruuca sirta ah ee Rijandel","text":"Qayb isbarbardhig ah oo ah 10+ Rijndael oo fulinaya dhamaan 128-, 192-, iyo 256-bit. Dib-u-soo-celinta algorithm-ka xasaasiga ah ee luqadaha oo dhan waa layli edbin ah oo qeexid sax ah, habdhaqan la tijaabin karo, iyo xadka qaadidda heerka luqadda, dhammaan dareenada waxtarka leh ee nidaamyada gacanta ku haya xogta xasaasiga ah.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Mod Minecraft ah oo ku dara qalab gaar ah, hub, mobsiyo, baloogyo, cabbiro, iyo astaamo kaloo badan oo ciyaarta ah. Lagu dhisay noocyada Java 8-17 ee xulashada noocyada Minecraft inta u dhaxaysa 1.16 iyo 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Tiger Programming Language","text":"Luqadda barnaamijka gaarka ah iyo turjubaanka lagu dhisay Go si ay u sahamiso luuqadda naqshadaynta runtime, dhaqanka fulinta, iyo wax-is-dhaafsiga waxqabadka. Isku-dubbarididda WebAssembly iyo ku-daridda faylalka-kooxdu waxay abuurtaa wax soo saar dhab ah, oo la baari karo oo loogu talagalay injineernimada heerka-nidaamyada halkii ay uga tegi lahayd shaqada sidii tijaabada kayd-kaliya.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Shabakadda Faa\'iidooyinka Tiger Tailgating","text":"Websaydh React ah oo loo dhiibay Clemson, SC ganacsiga dabada. Shaqadu waxay u tarjuntaa wax-soo-saarka ganacsiga yar-yar safar macaamiil oo cad iyo joogitaanka mareegaha la isku halayn karo, iyada oo la adeegsanayo fikirka badeecada si ay u caawiso urur dhab ah oo u rogo xiisaha. weydiimaha iyo dakhliga.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Mashruuca Turing Machine","text":"Qoyska ka badan 30+ hirgalinta Mashiinka Turing. Waxa loo adeegsaday in lagu muujiyo dhammaystirka luuqadaha barnaamijyada kala duwan ee cilmi-baadhista, gaar ahaan Luuqadda Programming-ka ee Shabeelka.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Tiger Programming Language"},"contact":{"title":"ila soo xidhiidh","header":"Macluumaadka Xiriirka","email":"pattygsocials@gmail.com","description":"Waxaan ka jawaabaa su\'aalaha iimaylka iyo fariimaha LinkedIn. Sidoo kale waan soo wici doonaa haddii lambarkayga lagu bixiyo resume ama si kale, in kastoo aan doorbido inaan lambarkayga ka dhigo mid gaar ah."},"formatter":{"title":"JSON & YAML Linter","description":"Qalabka tayada xogta ku salaysan browser-ka kaas oo ansixiya oo qaabeeya JSON iyo YAML iyadoo la isticmaalayo Go engine oo lagu soo ururiyay WebAssembly. Nashqaduhu waxa ay ku hayaan u kala shaandheynta u dhow isticmaalaha si degdeg ah, jawaab celin gaar ah iyada oo la xoojinayo xeerarka syntax dhabta ah ee xadka xogta. Waa tusaale kooban oo naqshadaynta socodka shaqo ee horumariye la isku halayn karo oo ku wareegsan saxnaanta, waxqabadka, iyo kalsoonida.","more_info1":"Wixii macluumaad dheeraad ah, tixraac README ee ku jira","more_info2":"Kaydka qaabeeyaha JSON/YAML.","format_as":"Qaabka Sida:","auto_detect":"Ogaanshaha otomaatiga ah","format":"Lint & Qaabka","valid_json":"\u2713 Sax ah JSON","valid_yaml":"\u2713 YAML sax ah","invalid_json":"JSON aan sax ahayn","invalid_yaml":"YAML aan sax ahayn","empty_input":"Fadlan geli qaar ka mid ah JSON ama YAML si aad u gasho.","too_large":"Gelida oo aad u weyn (ugu badnaan 1MB waa la ogol yahay).","fixed_yaml_spacing":"\u26a0 YAML waxay lahayd kala dheerayn/gelis aan sax ahayn laakiin si toos ah ayaa loo hagaajiyay oo loo qaabeeyey.","loading":"Soodejinaya qaabeeyaha...","waiting_for_input":"Sugaya gelinta...","load_failed":"Aan awoodin inuu soo dejiyo qaabeeyaha","output":"Natiijada:","input_code":"Gelida","json_examples":"Tusaalooyinka JSON","yaml_examples":"YAML Tusaalooyinka"},"tiger":{"title":"Luuqadda Shabeelka","description":"Tiger waa luuqad barnaamijeed caado u ah iyo Turjubaanka Go loo dhisay si uu u sahamiyo qaab dhismeedka runtime, semantics luqadda, iyo ganacsiyada waxqabadka. Isku-dubarid turjubaanka WebAssembly waxay u beddeshaa in nidaamyadu u shaqeeyaan is dhexgal, badeecad ku salaysan browserka: isticmaalayaashu waxay si toos ah u fulin karaan barnaamijyada iyada oo wakhtiga runtu uu yahay mid la qaadi karo oo ka go\'an codsiga martida loo yahay.","more_info1":"Wixii macluumaad dheeraad ah, tixraac README ee ku jira","more_info2":"Tiger Programming Language GitHub Kaydka.","select_engine":"Dooro Matoorka:","tiger_code":"Lambarka Shabeelka:","run_tiger":"Orod Shabeel","output":"Natiijada:"},"tab":{"title":"Patrick Goodwin","description":"Injineer buuxa oo buuxa oo leh 6+ sano oo waayo-aragnimo ah naqshadaynta alaabada SaaS, nidaamyada wax soo saarka, iyo software dakhli-abuurista."},"copy":{"text":"Nuqul","copied":"la guuriyay!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"I soo raac"},"languages":{"title":"Turjumaan Portfolio","description":"Soo ogow sida faylalkayga ay u heli karaan booqdayaasha adduunka oo dhan ka yimid iyagoo taageero ka helaya in ka badan 100 luqadood.","global_accessibility":{"title":"Helitaanka Caalamiga ah","description":"Bootfooliyadayda ayaa lagu heli karaa in ka badan {count} luqadood, taasoo ka dhigaysa mid la heli karo booqdayaasha adduunka oo dhan. Habkan luuqadaha badan ku hadlaa waxa ay ina tusinaysaa sida ay iga go\'an tahay ku darida iyo gaadhista caalamiga ah ee horumarinta software.","stats":{"languages_supported":"Luuqadaha la taageeray","countries_represented":"Waddamada Matalaya","continents_covered":"Qaaradaha Qarsoon"}},"features":{"title":"Astaamaha","items":[{"title":"Turjumaada-waqtiga dhabta ah:","description":"U beddel luqadaha isla markaaba xulashada luqadda"},{"title":"Luuqad ku salaysan URL:","description":"Xulashada luqadda waxa lagu xafiday URL"},{"title":"Taageerada Qoraalka Hooyo:","description":"U gudbinta saxda ah ee qoraallada sida Carabiga, Shiinaha, Hindi, iyo in ka badan"},{"title":"Dareenka Dhaqanka:","description":"Turjumaada waxay tixgeliyaan macnaha guud, ma aha oo kaliya macnaha dhabta ah"},{"title":"SEO La Habeeyay:","description":"Kala duwanaanshiyaha luuqad kasta waxaa loo habeeyay matoorada raadinta"}]},"world_map":{"title":"Khariidadda Adduunka Interactive","description":"dul hee dalalka khariidada si aad u aragto afafkooda la taageeray:","languages_label":"Luuqadaha","legend":{"supported":"Luuqadaha la taageeray","not_supported":"Ma jirto Taageero Luuqad"},"zoom_controls":{"zoom_in":"Soo dhawoow","zoom_out":"Soo Dhawayn","reset":"Dib-u-dejinta Muuqaalka"}},"supported_languages":{"title":"Luuqadaha la taageeray"},"interactive_country_map":{"title":"Khariidadda Dalka ee Is-dhexgalka","description":"U wareeg wadamada hoose si aad u aragto luqadahooda la taageeray:","language_count":{"single":"luqadda","multiple":"luqadaha"}},"tooltips":{"no_language_support":"Ma jiro taageero luqadeed"}},"logotext":"PATRICK"}')}}]);